entries[127111] = { ["name"] = "Eiskälte", ["text"] = "12% von Grundmana 45 Meter Reichweite\nSofort 25 sek. Abklingzeit\nFügt Gegnern in einem Radius von 8 Metern um den Zielort [Quellwert] Frostschaden zu und friert sie bis zu 8 Sek. lang fest. Erlittener Schaden kann den Effekt unterbrechen. [ Eisige Finger : Gewährt dem Magier für jedes von 'Eiskälte' betroffene Ziel eine Aufladung 'Eisige Finger' ]", ["unresolvedValues"] = true }
entries[127113] = { ["name"] = "Geistereisenbolzen", ["text"] = "Wirken in 1.5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nGeistereisenbarren (3)\n(2)" }
entries[127114] = { ["name"] = "Hochexplosives Schwarzpulver", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGeistereisenbarren\nGeistereisen lässt sich zu winzig kleinen Spänen verarbeiten, die starke Explosionseigenschaften entwickeln.\n(2)" }
entries[127115] = { ["name"] = "Fürst von Schmetternichs Todeszielfernrohr", ["text"] = "Wirken in 1.5 sek. 5\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (18), Rubellit (2), Geist der Harmonie\nFürst von Schmetternichs Todeszielfernrohr\n85\nBenutzen: Bringt Fürst von Schmetternichs Todeszielfernrohr dauerhaft an einer Fernkampfwaffe an, sodass manchmal Eure Beweglichkeit 10 Sek. lang um 1800 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[127116] = { ["name"] = "Verspiegeltes Zielfernrohr", ["text"] = "Wirken in 1.5 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGeistereisenbolzen (4), Lapislazuli (2)\nVerspiegeltes Zielfernrohr\n85\nBenutzen: Bringt ein verspiegeltes Zielfernrohr dauerhaft an einer Fernkampfwaffe an, sodass manchmal Euer kritischer Trefferwert 10 Sek. lang um 900 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
