entries[127625] = { ["name"] = "Glyphe 'Lichtquell'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nGlyphe 'Lichtbrunnen'\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Lichtbrunnen heilt nicht mehr automatisch Ziele in der Nähe, kann aber von Spielern angeklickt werden, woraufhin er 50% mehr heilt als normalerweise." }
entries[127626] = { ["name"] = "Verschlingende Seuche", ["text"] = "Sofort\nVerbraucht alle Schattenkugeln, um dem Ziel 0 Schattenschaden zuzufügen und es 6 Sek. lang alle 1.00 Sek. zusätzlich 0 Schattenschaden erleiden zu lassen. Heilt den Zaubernden außerdem um 1% seiner Maximalgesundheit, wenn der Zauber regelmäßigen Schaden verursacht.\n\nDas Ausmaß des Schadens und der Heilung hängen von der Anzahl der verbrauchten Schattenkugeln ab. [ Trost und Wahnsinn : Während 'Verschlingende Seuche' aktiv ist, wird der Schaden von 'Gedankenschinden' pro verbrauchter Schattenkugel um 33% erhöht ]" }
entries[127627] = { ["name"] = "Kaskade", ["text"] = "40 Meter Reichweite\nSofort\nSchleudert dem Ziel ein Schattengeschoss entgegen, das zunehmend stärker wird und Gegnern ( 12592 * 0.4) bis 12592 Schattenschaden zufügt oder Verbündete um ( 12592 * 0.4) bis 12592 heilt.\n\nDieser Effekt kann entweder von Verbündetem zu Verbündetem springen oder von Gegner zu Gegner. Mit jedem Sprung teilt sich das Geschoss in 2 Geschosse auf, die weiter entfernte Ziele bevorzugen und nie das gleiche Ziel zwei Mal treffen. 'Kaskade' kann bis zu 4-mal springen." }
